# Games and plays people know by name. teams = [away, home] in the schedule file's codes, score = (away, home).
# tease never names the people or the game; matchup, final and who are the three clues, in the order they open.
def G(name, date, teams, score, when, tease, matchup, final, who, aka=()):
    return dict(name=name, date=date, teams=teams, score=score, when=when, tease=tease, matchup=matchup, final=final, who=who, aka=list(aka))

